mapper.select:
select u.*, case when u.limit_id is null then 'N' else 'Y' end as limit_yn from () u
 order by u.last_at desc, u.item_id, u.char_id
 limit #{limit}

select i.item_id, i.item_cd, i.item_nm, c.char_id, c.char_no, c.char_nm, c.data_type, c.unit_nm, c.scale,
       p.proc_id, p.proc_cd, p.proc_nm
  from mst_item i
  join qms_char c on c.char_id = #{charId}
  left join mst_proc p on p.proc_id = #{procId}
 where i.item_id = #{itemId}

mapper.update:
update qms_spc_limit set status = 'VOID', void_reason = #{reason}, voided_by = #{by}, voided_at = now(),
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where limit_id = #{id} and status = 'ACTIVE' and row_ver = #{rowVer}
